'use strict';

// Shared report shell; all rankings and photos belong to the selected analysis.
const HAIR_REPORT_BASE=canonicalReport;
STUDIO_HAIRCUTS.forEach(c=>{if(c.image?.includes('hair-lob-soft-v2'))c.image='/assets/hair-lob-front-cutout.png';if(c.id==='cascade')c.image='/assets/hair-cascade-cutout.png';if(c.id==='bob')c.image='/assets/hair-bob-cutout.png';});
const HAIR_PANEL_BASE=canonicalHairPanel;
const HAIR_ADVICE=[
  {art:'/assets/hair-volume-front-cutout.png',symbol:'/assets/hair-volume-symbol.png',alt:'Mannequin de face, volume concentré sur les côtés',title:'Trop de volume sur les côtés',alternative:'Préférez un volume mieux réparti',text:'Un volume concentré uniquement sur les côtés peut élargir visuellement la zone la plus présente du visage.'},
  {art:'/assets/hair-bob-cutout.png',symbol:'/assets/hair-lines-symbol.png',alt:'Mannequin de face, carré aux contours droits et nets',title:'Lignes trop rigides',alternative:'Préférez des contours plus souples',text:'Un contour plus souple accompagne mieux vos proportions. Adaptez la ligne et le dégradé avec votre coiffeur.'},
  {art:'/assets/hair-fringe-cutout.png',symbol:'/assets/hair-fringe-symbol.png',alt:'Mannequin de face, frange pleine couvrant le front',title:'Frange trop dense',alternative:'Préférez une frange légère',text:'Gardez de la légèreté et adaptez la frange à votre implantation. Ce sont des pistes à discuter au salon, pas des interdictions.'}
];
function hairReportProfile(r){return r.hairProfile||r.answers||{};}
function hairReportCuts(r){return STUDIO_HAIRCUTS.slice().sort((a,b)=>studioHairScore(b,hairReportProfile(r))-studioHairScore(a,hairReportProfile(r)));}
function hairReferenceIcon(index){const advice=HAIR_ADVICE[index];return advice?`<img class="hair-reference-icon" src="${advice.symbol}" alt="" aria-hidden="true" width="34" height="34">`:'';}
function hairReportHeading(title,subtitle='',face=false){return `<header class="hair-report-heading"><span>${face?'Rapport visage':'Rapport cheveux'}</span><h1 tabindex="-1">${esc(title)}</h1>${subtitle?`<p>${esc(subtitle)}</p>`:''}</header>`;}
function hairReportCut(c,r,featured=false){return A(`<span class="hair-report-art">${studioHairTile(c)}</span><span class="hair-report-cut-copy">${featured?'<small class="hair-report-pick">Notre sélection</small>':''}<strong>${esc(c.name)}</strong><small>${esc(c.length)}</small>${featured?`<span class="hair-report-fit">${esc(c.id==='lob-soft'?'Élégante et naturelle.':uxHairFit(c,hairReportProfile(r)))}</span><span class="hair-report-discover">Découvrir ${icon('arrow')}</span>`:`<span class="hair-ref-circle">${icon('chev')}</span>`}</span>`,'haircut-open',{id:c.id,analysis:r.id,label:'Découvrir '+c.name},featured?'hair-report-feature':'hair-report-alternative');}
function hairCutsPanel(r){const cuts=hairReportCuts(r);return `<div class="hair-report-cuts">${hairReportHeading('Vos coupes signature')}${cuts.length?hairReportCut(cuts[0],r,true):'<p>Aucune coupe disponible.</p>'}<section class="hair-report-alternatives"><header><h2>À explorer aussi</h2>${A('Tout voir '+icon('chev'),'hair-more',{},'hair-report-link')}</header><div>${cuts.slice(1,3).map(c=>hairReportCut(c,r)).join('')}</div></section>${hairTrialsEntry()}</div>`;}
function hairFacePanel(r){const p=hairReportProfile(r),shape=String(r.faceShape||p.shape||'À préciser').replace(' — déclaré',''),cut=hairReportCuts(r)[0];return `<div class="hair-report-face">${hairReportHeading('Les lignes de votre visage','Une analyse personnalisée pour vous.',true)}<section class="hair-report-portrait">${beautyPortrait(r,'hair-report-photo')}<div class="hair-editorial-facts"><div class="hair-report-shape"><span>Votre analyse</span><strong>${esc(shape)}</strong></div><div class="hair-report-facts">${[['face','Texture',p.texture],['waves','Longueur',p.length],['sparkles','Style idéal',cut?.name]].map(([glyph,label,value])=>`<section>${icon(glyph)}<span><small>${label}</small><strong>${esc(value||'À préciser')}</strong></span></section>`).join('')}</div></div></section>${cut?A(`<span class="hair-report-mini-art">${studioHairTile(cut)}</span><span><small>Votre coupe repère</small><strong>${esc(cut.name)}</strong></span><span class="hair-ref-circle">`+icon('chev')+'</span>','haircut-open',{id:cut.id,analysis:r.id},'hair-report-row hair-report-face-cut'):''}<p class="hair-report-note">${/vision\//.test(r.source||'')?'Les repères de votre rapport.':'Aperçu de démonstration, sans mesure du visage.'}</p></div>`;}
function hairAvoidPanel(r){return `<div class="hair-report-avoid">${hairReportHeading('Les détails à éviter')}<div class="hair-report-advice-list">${HAIR_ADVICE.map((a,index)=>A(`<span class="hair-report-advice-top">0${index+1}</span><span class="hair-ref-advice-art"><img src="${a.art}" alt="${esc(a.alt)}, sans traits du visage"></span><span class="hair-ref-advice-copy"><span class="hair-report-advice-icon">${hairReferenceIcon(index)}</span><strong>${esc(a.title.replace(/^Le |^Les |^Une /,''))}</strong><span class="hair-report-instead">${esc(a.alternative)}</span></span><span class="hair-ref-circle">${icon('chev')}</span>`,'hair-report-advice',{index,analysis:r.id},'hair-report-advice-card')).join('')}</div></div>`;}
canonicalHairPanel=function(tab,r){return tab==='Coupes'?hairCutsPanel(r):tab==='Visage'?hairFacePanel(r):tab==='À éviter'?hairAvoidPanel(r):HAIR_PANEL_BASE(tab,r);};
canonicalReport=function(){const r=report();if(!r||r.domain!=='Cheveux'||!canonicalOwned())return HAIR_REPORT_BASE();const tabs=canonicalReportTabs(r.domain,r),step=Math.max(0,Math.min(Number(M.canonicalReportStep)||0,tabs.length-1));return beautyPage(canonicalReportRail(tabs,step)+`<section class="canonical-report-panel beauty-report-panel hair-report-content" aria-live="polite" aria-label="${esc(tabs[step])}">${canonicalHairPanel(tabs[step],r)}</section>`+(tabs[step]==='Essais'?'':beautyFooter(r)),'beauty-report hair-report');};
ACTIONS['hair-report-advice']=data=>{if(!canonicalOwned())return;const r=M.analyses.find(x=>x.id===data.analysis&&x.domain==='Cheveux'),a=HAIR_ADVICE[Number(data.index)];if(!r||!a)return;modal('À éviter : '+a.title,`<div class="hair-report-advice-detail"><span class="hair-report-advice-icon">${hairReferenceIcon(Number(data.index))}</span><h3>${esc(a.alternative)}</h3><p>${esc(a.text)}</p></div>`+A('Revenir au rapport','close',{},'beauty-button is-secondary'));};
// Preserve the existing try-on flow and its entitlement and photo checks.
ACTIONS['haircut-open']=data=>{const cut=STUDIO_HAIRCUTS.find(c=>c.id===data.id);if(!cut)return;const r=data.analysis?M.analyses.find(x=>x.id===data.analysis&&x.domain==='Cheveux'):null;if(data.analysis&&(!r||!canonicalOwned()))return;M.haircutSelected=cut.id;const p=r?hairReportProfile(r):M.hairProfile;modal(cut.name,`<div class="hair-report-cut-detail"><div class="hair-report-detail-art">${studioHairTile(cut,true)}</div><div class="hair-report-detail-tags"><span>${esc(cut.length)}</span><span>${esc(cut.care)}</span></div>${p?`<h3>${esc(uxHairFit(cut,p))}</h3>`:''}<p>${esc(cut.reason)}</p><details><summary>À dire au salon ${icon('chev')}</summary><p>${esc(cut.salon)}</p></details></div>`+A(icon('sparkles')+'<span>Essayer sur ma photo</span>','haircut-simulate',{id:cut.id,analysis:data.analysis},'beauty-button is-copper')+A('Revenir aux coupes','close',{},'hair-report-link'));};

const HAIR_HOME_BASE=V['HAI-01'];
V['HAI-01']=()=>{const selected=report(),r=selected?.domain==='Cheveux'?selected:M.analyses.filter(x=>x.domain==='Cheveux'&&x.status==='complete').at(-1);if(!r||!canonicalOwned())return HAIR_HOME_BASE();M.context.analysis=r.id;return canonicalReport();};
V['HAI-02']=()=>{const filter=M.hairLengthFilter||'Toutes',cuts=STUDIO_HAIRCUTS.filter(c=>filter==='Toutes'||c.length===filter).sort((a,b)=>a.name.localeCompare(b.name)),pages=Math.max(1,Math.ceil(cuts.length/6)),page=Math.max(0,Math.min(M.hairCatalogueSelection?.filter===filter?M.hairCatalogueSelection.page:0,pages-1));return beautyPage(`<div class="hair-catalogue">${hairReportHeading(M.hairTrialChoosing?'Choisissez une coupe':'Trouvez votre prochaine coupe')}${chips(['Toutes','Très court','Court','Mi-long','Long'],'hairLengthFilter',filter)}<div class="hair-catalogue-grid">${cuts.slice(page*6,page*6+6).map(c=>A(`<span class="hair-report-art">${studioHairTile(c)}</span><strong>${esc(c.name)}</strong><small>${esc(c.length)}</small>`,M.hairTrialChoosing?'hair-trial-select':'haircut-open',{id:c.id},'hair-catalogue-cut')).join('')}</div><div class="hair-catalogue-pagination">${page>0?A(icon('back'),'hair-catalogue-page',{page:page-1,label:'Page précédente'},'hair-report-link'):'<span></span>'}<span>${page+1} / ${pages}</span>${page<pages-1?A(icon('arrow'),'hair-catalogue-page',{page:page+1,label:'Page suivante'},'hair-report-link'):'<span></span>'}</div>${A(icon('sparkles')+'<span>Mes essais coiffure</span>'+icon('chev'),'saved-hair-sims',{},'hair-report-row')}</div>`,'hair-report');};
ACTIONS['hair-catalogue-page']=data=>{M.hairCatalogueSelection={filter:M.hairLengthFilter||'Toutes',page:Math.max(0,Number(data.page)||0)};render();};
